from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        S = sum(nums)
        OFF = S if S > 0 else 1
        if k < -OFF or k > OFF:
            return -1
        # generate valid products (products of values 2..12, times 1) <= limit
        prods = {1}
        stack = [1]
        while stack:
            p = stack.pop()
            for v in range(2, 13):
                q = p * v
                if q <= limit and q not in prods:
                    prods.add(q)
                    stack.append(q)
        plist = sorted(prods)
        idx = {p: i for i, p in enumerate(plist)}
        n_p = len(plist)
        ZERO = n_p
        OV = n_p + 1
        total = n_p + 2

        trans = [[0] * 13 for _ in range(total)]
        for i, p in enumerate(plist):
            row = trans[i]
            for v in range(13):
                if v == 0:
                    row[v] = ZERO
                else:
                    q = p * v
                    row[v] = idx[q] if q <= limit else OV
        for v in range(13):
            trans[ZERO][v] = ZERO
            trans[OV][v] = ZERO if v == 0 else OV

        dp0 = [0] * total  # next index even -> add value
        dp1 = [0] * total  # next index odd -> subtract value
        base = 1 << OFF

        for v in nums:
            n0 = dp0[:]
            n1 = dp1[:]
            for i in range(total):
                a = dp0[i]
                b = dp1[i]
                if a or b:
                    j = trans[i][v]
                    if a:
                        n1[j] |= a << v
                    if b:
                        n0[j] |= b >> v
            # singleton start
            if v == 0:
                j = ZERO
            else:
                j = idx[v] if v <= limit else OV
            n1[j] |= base << v
            dp0, dp1 = n0, n1

        bit = 1 << (k + OFF)
        ans = -1
        for i, p in enumerate(plist):
            if (dp0[i] | dp1[i]) & bit:
                if p > ans:
                    ans = p
        if (dp0[ZERO] | dp1[ZERO]) & bit:
            if 0 > ans:
                ans = 0
        return ans

