class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(N):
            if N < 1:
                return 0
            s = str(N)
            n = len(s)

            @lru_cache(None)
            def dp(pos, tight, started, ssum, prod):
                if pos == n:
                    if not started:
                        return 0
                    if prod == 0:
                        return 1
                    return 1 if prod % ssum == 0 else 0
                lim = int(s[pos]) if tight else 9
                res = 0
                for d in range(0, lim + 1):
                    nt = tight and (d == lim)
                    if not started and d == 0:
                        res += dp(pos + 1, nt, False, 0, 1)
                    else:
                        if prod == 0 or d == 0:
                            res += dp(pos + 1, nt, True, 0, 0)
                        else:
                            res += dp(pos + 1, nt, True, ssum + d, prod * d)
                return res

            ans = dp(0, True, False, 0, 1)
            dp.cache_clear()
            return ans

        return count(r) - count(l - 1)

