class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = [dict()]
        cnt = [0]
        depth = [0]

        for w in words:
            node = 0
            cnt[0] += 1
            for ch in w:
                ch_map = children[node]
                nxt = ch_map.get(ch)
                if nxt is None:
                    nxt = len(cnt)
                    children.append(dict())
                    cnt.append(0)
                    depth.append(depth[node] + 1)
                    ch_map[ch] = nxt
                node = nxt
                cnt[node] += 1

        M1 = 0
        kp1 = k + 1
        for node in range(len(cnt)):
            if cnt[node] >= kp1:
                d = depth[node]
                if d > M1:
                    M1 = d

        groups = {}
        gid = [-1] * n

        for i in range(n):
            w = words[i]
            node = 0
            g = -1
            best = 0
            for ch in w:
                node = children[node][ch]
                c = cnt[node]
                if c < k:
                    break
                if c == k:
                    if g == -1:
                        g = node
                    best = depth[node]
                # if c > k continue
            gid[i] = g
            if g != -1:
                # all words in a group share the same deepest node
                prev = groups.get(g)
                if prev is None or best > prev:
                    groups[g] = best

        d1 = -1
        g1 = -1
        d2 = -1
        for g, d in groups.items():
            if d > d1:
                d2 = d1
                d1 = d
                g1 = g
            elif d > d2:
                d2 = d

        ans = [0] * n
        for i in range(n):
            if gid[i] == g1 and g1 != -1:
                x = d2
            else:
                x = d1
            v = M1
            if x > v:
                v = x
            if v < 0:
                v = 0
            ans[i] = v
        return ans

