class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
    def add_edge(self, fr, to, cap):
        forward = [to, cap, None]
        backward = [fr, 0, None]
        forward[2] = backward
        backward[2] = forward
        self.graph[fr].append(forward)
        self.graph[to].append(backward)
    def bfs(self, s, t):
        self.level = [-1]*self.n
        q = deque([s])
        self.level[s] = 0
        while q:
            v = q.popleft()
            for e in self.graph[v]:
                if e[1] > 0 and self.level[e[0]] < 0:
                    self.level[e[0]] = self.level[v] + 1
                    q.append(e[0])
        return self.level[t] >= 0
    def dfs(self, v, t, f):
        if v == t:
            return f
        while self.it[v] < len(self.graph[v]):
            e = self.graph[v][self.it[v]]
            to, cap = e[0], e[1]
            if cap > 0 and self.level[v] < self.level[to]:
                d = self.dfs(to, t, min(f, cap))
                if d > 0:
                    e[1] -= d
                    e[2][1] += d
                    return d
            self.it[v] += 1
        return 0
    def max_flow(self, s, t, limit):
        flow = 0
        while self.bfs(s, t):
            self.it = [0]*self.n
            while True:
                f = self.dfs(s, t, 10**18)
                if f == 0:
                    break
                flow += f
                if flow > limit:
                    return flow
        return flow

