class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        byB = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            byB[b].append((a, i))
        best1 = 0
        best1idx = -1
        best2 = 0
        gain = [0] * len(conflictingPairs)
        base = 0
        for r in range(1, n + 1):
            for a, idx in byB[r]:
                if a > best1:
                    best2 = best1
                    best1 = a
                    best1idx = idx
                elif a > best2:
                    best2 = a
            base += r - best1
            if best1idx >= 0:
                gain[best1idx] += best1 - best2
        return base + max(gain)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        s2 = str2.encode()
        word = bytearray(b'a' * L)
        fixed = bytearray(L)
        maxEnd = 0
        for i, c in enumerate(str1):
            if c == 'T':
                if maxEnd > i:
                    ov = min(maxEnd, i + m)
                    if word[i:ov] != s2[:ov - i]:
                        return ""
                    if i + m > maxEnd:
                        word[maxEnd:i + m] = s2[maxEnd - i:]
                        fixed[maxEnd:i + m] = b'\x01' * (i + m - maxEnd)
                        maxEnd = i + m
                else:
                    word[i:i + m] = s2
                    fixed[i:i + m] = b'\x01' * m
                    maxEnd = i + m

        B = ord('b')
        for i, c in enumerate(str1):
            if c == 'F':
                if word[i:i + m] == s2:
                    # find last free position in [i, i+m-1]
                    k = i + m - 1
                    found = -1
                    while k >= i:
                        if not fixed[k]:
                            found = k
                            break
                        k -= 1
                    if found < 0:
                        return ""
                    word[found] = B
                    fixed[found] = 1

        return word.decode()

