class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 2)
        for i in range(1, n + 2):
            fact[i] = fact[i-1] * i

        def f(o, e, p):
            # p = 1 means next element must be odd, 0 means even
            if o == 0 and e == 0:
                return 1
            if p == 1:
                if o - e == 0 or o - e == 1:
                    return fact[o] * fact[e]
                return 0
            else:
                if e - o == 0 or e - o == 1:
                    return fact[o] * fact[e]
                return 0

        avail = list(range(1, n + 1))
        o = (n + 1) // 2
        e = n // 2
        # total
        total = f(o, e, 1) + f(o, e, 0)
        if k > total:
            return []
        res = []
        req = -1
        for pos in range(n):
            for idx, x in enumerate(avail):
                if req != -1 and x % 2 != req:
                    continue
                no = o - (1 if x % 2 == 1 else 0)
                ne = e - (1 if x % 2 == 0 else 0)
                nextp = 1 - (x % 2)
                cnt = f(no, ne, nextp)
                if cnt == 0:
                    continue
                if k > cnt:
                    k -= cnt
                else:
                    res.append(x)
                    avail.pop(idx)
                    o, e = no, ne
                    req = nextp
                    break
            else:
                return []
        return res

