class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]
        nxt = [2, 2, 0]  # nxt[0]=2, nxt[1]=2, nxt[2]=0

        # g[d][i][j]: straight run length starting at (i,j) going in dir d (no turns)
        g = [[[0] * m for _ in range(n)] for _ in range(4)]
        for d in range(4):
            dr, dc = dirs[d]
            rows = range(n) if dr == -1 else range(n - 1, -1, -1)
            cols = range(m) if dc == -1 else range(m - 1, -1, -1)
            gd = g[d]
            for i in rows:
                gi = gd[i]
                row = grid[i]
                ni = i + dr
                if 0 <= ni < n:
                    gni = gd[ni]
                    gridni = grid[ni]
                else:
                    gni = None
                    gridni = None
                for j in cols:
                    v = 1
                    if gni is not None:
                        nj = j + dc
                        if 0 <= nj < m and gridni[nj] == nxt[row[j]]:
                            v = 1 + gni[nj]
                    gi[j] = v

        # f[d][i][j]: run starting at (i,j) in dir d with at most one clockwise turn remaining
        f = [[[0] * m for _ in range(n)] for _ in range(4)]
        for d in range(4):
            dr, dc = dirs[d]
            dr2, dc2 = dirs[(d + 1) % 4]
            gturn = g[(d + 1) % 4]
            rows = range(n) if dr == -1 else range(n - 1, -1, -1)
            cols = range(m) if dc == -1 else range(m - 1, -1, -1)
            fd = f[d]
            for i in rows:
                fi = fd[i]
                row = grid[i]
                ni = i + dr
                if 0 <= ni < n:
                    fni = fd[ni]
                    gridni = grid[ni]
                else:
                    fni = None
                    gridni = None
                ni2 = i + dr2
                if 0 <= ni2 < n:
                    gni2 = gturn[ni2]
                    gridni2 = grid[ni2]
                else:
                    gni2 = None
                    gridni2 = None
                for j in cols:
                    want = nxt[row[j]]
                    best = 0
                    if fni is not None:
                        nj = j + dc
                        if 0 <= nj < m and gridni[nj] == want:
                            t = fni[nj]
                            if t > best:
                                best = t
                    if gni2 is not None:
                        nj2 = j + dc2
                        if 0 <= nj2 < m and gridni2[nj2] == want:
                            t = gni2[nj2]
                            if t > best:
                                best = t
                    fi[j] = 1 + best

        ans = 0
        for i in range(n):
            row = grid[i]
            for j in range(m):
                if row[j] == 1:
                    for d in range(4):
                        v = f[d][i][j]
                        if v > ans:
                            ans = v
        return ans

from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        parts = p.split('*')
        # exactly two '*' -> three parts
        a, b, c = parts[0], parts[1], parts[2]

        def occurrences(pat):
            if pat == "":
                return list(range(n + 1))
            m = len(pat)
            if m > n:
                return []
            # KMP
            fail = [0] * m
            k = 0
            for i in range(1, m):
                while k > 0 and pat[i] != pat[k]:
                    k = fail[k - 1]
                if pat[i] == pat[k]:
                    k += 1
                fail[i] = k
            res = []
            k = 0
            for i in range(n):
                ch = s[i]
                while k > 0 and ch != pat[k]:
                    k = fail[k - 1]
                if ch == pat[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = fail[k - 1]
            return res

        A = occurrences(a)
        if not A:
            return -1
        B = occurrences(b)
        if not B:
            return -1
        C = occurrences(c)
        if not C:
            return -1

        la, lb, lc = len(a), len(b), len(c)
        best = -1
        # two pointers
        jb = 0
        for i in A:
            pos1 = i + la
            # find first j in B with j >= pos1
            jb = bisect_left(B, pos1, jb)
            if jb >= len(B):
                break
            j = B[jb]
            pos2 = j + lb
            kc = bisect_left(C, pos2)
            if kc >= len(C):
                break
            k = C[kc]
            total = k + lc - i
            if best == -1 or total < best:
                best = total
        return best

