def main():
    data = sys.stdin.buffer.read().split()
    M = 998244353
    N = int(data[0])
    A = [int(x) for x in data[1:1+N-1]]
    n = N - 1

    from collections import defaultdict
    primes_d = {}
    for idx, a in enumerate(A):
        x = a
        f = 2
        while f * f <= x:
            if x % f == 0:
                c = 0
                while x % f == 0:
                    x //= f
                    c += 1
                if f not in primes_d:
                    primes_d[f] = [0] * n
                primes_d[f][idx] = c
            f += 1
        if x > 1:
            if x not in primes_d:
                primes_d[x] = [0] * n
            primes_d[x][idx] = 1

    def powarray_np(base, L):
        k = int(L ** 0.5) + 1
        small = [1] * k
        for j in range(1, k):
            small[j] = small[j-1] * base % M
        bk = pow(base, k, M)
        big = [1] * k
        for j in range(1, k):
            big[j] = big[j-1] * bk % M
        sa = np.array(small, dtype=np.int64)
        ba = np.array(big, dtype=np.int64)
        arr = (np.outer(ba, sa) % M).ravel()[:L]
        return np.ascontiguousarray(arr)

    def solve_prime_py(p, d):
        S = sum(d); L = S + 1
        pw = [1] * L
        for h in range(1, L):
            pw[h] = pw[h-1] * p % M
        dp = [0] * L
        dp[0] = 1
        i = 1; j = 0
        while j < n:
            if d[j] == 0:
                t = 0
                while j < n and d[j] == 0:
                    t += 1; j += 1
                base = pow(p, t, M)
                cur = 1
                for h in range(L):
                    if dp[h]:
                        dp[h] = dp[h] * cur % M
                    cur = cur * base % M
                i += t
            else:
                dj = d[j]
                new = [0] * L
                pi = pow(p, i, M)
                for h in range(L):
                    v = dp[h]
                    if v:
                        hu = h + dj
                        if hu < L:
                            new[hu] = (new[hu] + v * pw[hu]) % M
                        if h >= dj:
                            new[h-dj] = (new[h-dj] + v * pw[h-dj]) % M
                        else:
                            new[0] = (new[0] + v * pow(pi, dj-h, M)) % M
                dp = new
                i += 1; j += 1
        return sum(dp) % M

    def solve_prime_np(p, d):
        S = sum(d); L = S + 1
        pw = powarray_np(p % M, L)
        dp = np.zeros(L, dtype=np.int64)
        dp[0] = 1
        i = 1; j = 0
        while j < n:
            if d[j] == 0:
                t = 0
                while j < n and d[j] == 0:
                    t += 1; j += 1
                base = pow(p, t, M)
                f = powarray_np(base, L)
                dp = dp * f % M
                i += t
            else:
                dj = d[j]
                new = np.zeros(L, dtype=np.int64)
                # up
                new[dj:] = dp[:L-dj] * pw[dj:] % M
                # down h>=dj
                new[:L-dj] = (new[:L-dj] + dp[dj:] * pw[:L-dj]) % M
                # down h<dj
                pi = pow(p, i, M)
                s = 0
                for h in range(dj):
                    v = int(dp[h])
                    if v:
                        s = (s + v * pow(pi, dj-h, M)) % M
                if s:
                    new[0] = (int(new[0]) + s) % M
                dp = new
                i += 1; j += 1
        return int(dp.sum() % M)

    ans = 1
    for p, d in primes_d.items():
        S = sum(d)
        if S == 0:
            continue
        if S + 1 > 64:
            r = solve_prime_np(p, d)
        else:
            r = solve_prime_py(p, d)
        ans = ans * r % M
    print(ans % M)

