class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(T):
            if T == 0:
                return True
            moves = 0
            cur = 0
            for i in range(n):
                p = points[i]
                k = -(-T // p)
                need = k - cur
                if need <= 0:
                    moves += 1
                    cur = 0
                else:
                    moves += 2 * need - 1
                    cur = need - 1
                if moves > m:
                    return False
            return moves <= m

        lo, hi = 0, ((m + 1) // 2) * max(points)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

