class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        n = len(target)
        full = 1 << n
        lcms = [1] * full
        for m in range(1, full):
            l = 1
            for i in range(n):
                if m >> i & 1:
                    l = l * target[i] // gcd(l, target[i])
            lcms[m] = l
        INF = float('inf')
        dp = [INF] * full
        dp[0] = 0
        # precompute submasks lists
        subs = []
        for mask in range(full):
            comp = (full - 1) ^ mask
            lst = []
            s = comp
            while s:
                lst.append(s)
                s = (s - 1) & comp
            subs.append(lst)
        for num in nums:
            newdp = dp[:]
            for mask in range(full):
                cur = dp[mask]
                if cur == INF:
                    continue
                for s in subs[mask]:
                    L = lcms[s]
                    c = (L - num % L) % L
                    t = mask | s
                    if cur + c < newdp[t]:
                        newdp[t] = cur + c
            dp = newdp
        return dp[full - 1]

