class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count(a, b, k):
            # number of pairs (x,y), 0<=x<=a, 0<=y<=b, x+y <= k-1
            m = min(a, k - 1)
            if m < 0:
                return 0
            total = 0
            # t = k-1-x ranges from k-1-m to k-1
            lo_t = k - 1 - m
            hi_t = k - 1
            # part where t >= b -> value b+1
            start = max(b, lo_t)
            if start <= hi_t:
                c1 = hi_t - start + 1
                total += c1 * (b + 1)
            # part where t < b -> value t+1
            hi2 = min(b - 1, hi_t)
            lo2 = lo_t
            if hi2 >= lo2:
                cnt = hi2 - lo2 + 1
                total += (lo2 + 1 + hi2 + 1) * cnt // 2
            return total

        def solve(is_max):
            left = [0] * n
            right = [0] * n
            stack = []
            for i in range(n):
                v = nums[i]
                if is_max:
                    while stack and nums[stack[-1]] <= v:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] >= v:
                        stack.pop()
                left[i] = stack[-1] if stack else -1
                stack.append(i)
            stack = []
            for i in range(n - 1, -1, -1):
                v = nums[i]
                if is_max:
                    while stack and nums[stack[-1]] < v:
                        stack.pop()
                else:
                    while stack and nums[stack[-1]] > v:
                        stack.pop()
                right[i] = stack[-1] if stack else n
                stack.append(i)
            res = 0
            for i in range(n):
                a = i - left[i] - 1
                b = right[i] - i - 1
                res += nums[i] * count(a, b, k)
            return res

        return solve(True) + solve(False)

