        if L <= 0 or m == 0:
            return m
        if A == B:
            r = L % A
            if r:
                m = ((m << r) | (m >> (A - r))) & full
            return m
        traj = cache.get(m)
        if traj is None:
            traj = [m]
            cur = m
            while cur != full and cur != 0:
                nb = 1 if (cur & sel) else 0
                cur = ((cur << 1) | nb) & full
                traj.append(cur)
            cache[m] = traj
        if L < len(traj):
            return traj[L]
        return traj[-1]

    mask = 1
    pos = 1
