class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7
        N = n + 1
        fact = [1]*(N+1)
        for i in range(1, N+1):
            fact[i] = fact[i-1]*i % MOD
        inv = [1]*(N+1)
        inv[N] = pow(fact[N], MOD-2, MOD)
        for i in range(N, 0, -1):
            inv[i-1] = inv[i]*i % MOD
        if k > n-1:
            return 0
        comb = fact[n-1]*inv[k] % MOD * inv[n-1-k] % MOD
        return m * comb % MOD * pow(m-1, n-1-k, MOD) % MOD

