class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        big = 0
        small = []
        for v in nums:
            if v > threshold:
                big += 1
            else:
                small.append(v)
        if not small:
            return big
        small.sort()
        n = len(small)
        idx = {v: i for i, v in enumerate(small)}
        parent = list(range(n))

        def find(x):
            r = x
            while parent[r] != r:
                r = parent[r]
            while parent[x] != r:
                parent[x], x = r, parent[x]
            return r

        first = [0] * (threshold + 1)  # 0 means unset, store i+1
        comps = n
        for i, d in enumerate(small):
            for m in range(d, threshold + 1, d):
                f = first[m]
                if f == 0:
                    first[m] = i + 1
                else:
                    a = find(f - 1)
                    b = find(i)
                    if a != b:
                        parent[a] = b
                        comps -= 1
        return comps + big
